[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$RequestPath,[Parameter(Mandatory=$true)][string]$OutputPath,[string]$RequestSchemaPath=(Join-Path $PSScriptRoot 'ai_design_controlled_run_request.schema.json'),[string]$RunStateSchemaPath=(Join-Path $PSScriptRoot 'ai_design_run_state.schema.json'),[string]$NodeRegistryPath=(Join-Path $PSScriptRoot 'AI_DESIGN_NODE_REGISTRY.json'),[string]$EdgeRegistryPath=(Join-Path $PSScriptRoot 'AI_DESIGN_CORE_EDGE_REGISTRY.json'),[string]$GraphContractPath=(Join-Path $PSScriptRoot 'AI_DESIGN_EXECUTION_GRAPH_CONTRACT.md'),[string]$GovernancePath=(Join-Path $PSScriptRoot 'AI_DESIGN_GOVERNANCE_ROUTE_MAPPING.json'))
$ErrorActionPreference='Stop';function J($p){Get-Content -LiteralPath $p -Raw|ConvertFrom-Json};function Get-FileSha256($p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLower()}
foreach($p in @($RequestPath,$RequestSchemaPath,$RunStateSchemaPath,$NodeRegistryPath,$EdgeRegistryPath,$GraphContractPath,$GovernancePath)){if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw"Missing $p"}};if(Test-Path $OutputPath){throw'Immutable output already exists'};if(-not(Test-Json -LiteralPath $RequestPath -SchemaFile $RequestSchemaPath -ErrorAction Stop)){throw'Request schema failed'}
$q=J $RequestPath;$root=[IO.Path]::GetFullPath($q.product_root);$passport=[IO.Path]::GetFullPath($q.passport_path);if(-not$passport.StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)){throw'Passport outside product root'};if(-not(Test-Path $passport -PathType Leaf)){throw'Passport missing'};if(-not(Test-Path $q.baseline_path -PathType Leaf)){throw'Baseline missing'}
$nr=J $NodeRegistryPath;$er=J $EdgeRegistryPath;$nodes=@($nr.nodes.node_id);$pending=@($nodes|Where-Object{$_-ne'N010_RUN_INITIALIZATION'})
$s=[ordered]@{schema_version='1.0';run_id=$q.run_id;execution_mode=$q.execution_mode;lifecycle_state='RUN_ACTIVE';launch_control=$q.launch_control;product_identity=[ordered]@{sku=$q.sku;model=$q.model;variant=$null;market=$q.market;channel=$q.channel;locales=@($q.locales);product_root=$root};pinned_graph=[ordered]@{graph_version='AI-DESIGN-GRAPH-1.8';graph_contract=[ordered]@{path='AI Design Conveyor/10_Runtime_Registry/AI_DESIGN_EXECUTION_GRAPH_CONTRACT.md';version='1.8';sha256=Get-FileSha256 $GraphContractPath};node_registry=[ordered]@{path='AI Design Conveyor/10_Runtime_Registry/AI_DESIGN_NODE_REGISTRY.json';version=$nr.registry_version;sha256=Get-FileSha256 $NodeRegistryPath};edge_registry=[ordered]@{path='AI Design Conveyor/10_Runtime_Registry/AI_DESIGN_CORE_EDGE_REGISTRY.json';version=$er.registry_version;sha256=Get-FileSha256 $EdgeRegistryPath};governance_mapping=[ordered]@{path='AI Design Conveyor/10_Runtime_Registry/AI_DESIGN_GOVERNANCE_ROUTE_MAPPING.json';version='1.2';sha256=Get-FileSha256 $GovernancePath}};pinned_product_truth=[ordered]@{artifact_id="PASSPORT-$($q.sku)";path=$passport;version=$q.passport_version;sha256=Get-FileSha256 $passport;status=$q.passport_status};node_state=[ordered]@{current_node_id='N010_RUN_INITIALIZATION';completed_node_ids=@();active_node_ids=@('N010_RUN_INITIALIZATION');pending_node_ids=$pending;blocked_node_ids=@();not_applicable_node_ids=@()};edge_state=[ordered]@{applied_edge_ids=@();available_edge_ids=@('E010_INITIALIZE_PASSPORT_ROUTE');rejected_edge_ids=@();unevaluated_edge_ids=@($er.edges.edge_id|Where-Object{$_-ne'E010_INITIALIZE_PASSPORT_ROUTE'})};artifacts=@();evidence_gaps=@();conflicts=@();blockers=@();approvals=@();budgets=[ordered]@{retry=[ordered]@{used=0;maximum=0};round=[ordered]@{used=0;maximum=0};cost=[ordered]@{currency='USD';approved=0;spent=0};time=[ordered]@{started_at=$q.created_at;deadline_at=$null}};side_effect_ledger=@();receipt_refs=@();transition_history=@();latest_checkpoint=$null;resume_cursor=$null;terminal=[ordered]@{is_terminal=$false;status='NOT_TERMINAL';terminal_receipt_ref=$null};created_at=$q.created_at;updated_at=$q.created_at}
$s.pinned_graph.graph_version='AI-DESIGN-GRAPH-2.5';$s.pinned_graph.graph_contract.version='2.5'
$parent=Split-Path -Parent $OutputPath;if(-not(Test-Path $parent -PathType Container)){throw'Output parent missing'};$tmp=Join-Path $parent ([IO.Path]::GetRandomFileName());try{$s|ConvertTo-Json -Depth 100|Set-Content -LiteralPath $tmp -Encoding UTF8 -NoNewline;if(-not(Test-Json -LiteralPath $tmp -SchemaFile $RunStateSchemaPath -ErrorAction Stop)){throw'Run State schema failed'};Move-Item $tmp $OutputPath}finally{if(Test-Path $tmp){Remove-Item $tmp -Force}}
Write-Output 'AI_DESIGN_CONTROLLED_RUN_INITIALIZATION=PASS';Write-Output "RUN_ID=$($q.run_id)";Write-Output "OUTPUT_SHA256=$(Get-FileSha256 $OutputPath)";Write-Output "EXTERNAL_SIDE_EFFECTS=0"
